entries[93325] = { ["name"] = "Schockwelle", ["text"] = "Nahkampfreichweite\nWirken in 1 sek.\nSendet vom Zaubernden aus eine Schockwelle nach vorne, die 3696 Schaden verursacht und alle feindlichen Ziele innerhalb von 15 Metern in einem kegelförmigen Bereich vor dem Zaubernden 3 Sek. lang betäubt." }
entries[93326] = { ["name"] = "Sandsteindrache", ["text"] = "Wirken in 1.5 sek.\nVerwandelt Euch in einen Sandsteindrachen, wodurch Ihr sehr schnell fliegen und einen Verbündeten auf dem Rücken tragen könnt. Das ist ein Flugreittier.\n\"Sandsteindrachen wurden vor langer Zeit ausgiebig vom berühmten Alchemisten Zander Flinkspross untersucht. Es wird sogar behauptet, dass Zander Tränke entwickelt hat, welche es ermöglichen, die Physiologie dieser Drachen nachzuahmen.\"\nBeruf:\nAlchemie" }
entries[93327] = { ["name"] = "Erdbestattung", ["text"] = "20 Meter Reichweite\nSofort\nErdrückt den Feind in einer irdenen Umklammerung und verursacht 30 Sek. lang alle 2 Sek. 341 Schaden. Zusätzliche Anwendungen erhöhen zwar den Schmerz, doch starke Winde können dem Effekt entgegenwirken." }
entries[93328] = { ["name"] = "Phiole der Sande", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nPyriumbeschichtete Kristallphiole , Sande der Zeit (8), Echtgold (12), Fläschchen der Winde (8), Fläschchen der Titanenstärke (8), Tiefsteinöl (8)\nBeruf:\nArchäologie\nBeute von:\nKanope\n\nPhiole der Sande\nReittier (Accountweit)\nBenutzen: Lehrt Euch, Euch in einen Drachen zu verwandeln, wodurch Ihr einen Verbündeten auf dem Rücken tragen könnt. Das ist ein Flugreittier.\nVerwandelt Euch in einen Sandsteindrachen, wodurch Ihr sehr schnell fliegen und einen Verbündeten auf dem Rücken tragen könnt. Das ist ein Flugreittier.\n1 - 80 ( 80)\nBenötigt Unerfahrenes Reiten\n\"Sandsteindrachen wurden vor langer Zeit ausgiebig vom berühmten Alchemisten Zander Flinkspross untersucht. Es wird sogar behauptet, dass Zander Tränke entwickelt hat, welche es ermöglichen, die Physiologie dieser Drachen nachzuahmen.\"\nBeruf:\nAlchemie" }
