entries[93402] = { ["name"] = "Sonnenfeuer", ["text"] = "1.8% von Grundmana 40 Meter Reichweite\nSofort\nWildheit, Wächter, Wiederherstellung\nEin schneller Sonnenlichtstrahl fügt dem Gegner (21.2% der Zaubermacht) Naturschaden sowie zusätzlich im Verlauf von 18 Sek. (165.6% der Zaubermacht) Naturschaden zu.\n\nGleichgewicht\nEin schneller Sonnenlichtstrahl fügt dem Gegner (21.2% der Zaubermacht) Naturschaden sowie zusätzlich im Verlauf von 18 Sek. (165.6% der Zaubermacht) Naturschaden zu.\n\nErzeugt 0 Astrale Macht." }
