entries[93433] = { ["name"] = "Bodenangriff", ["text"] = "10 Fokus, plus 5 pro Sek.\nKanalisiert (Wirken in 8 sek.) 14 sek. Abklingzeit\nDer Wurm gräbt sich in die Erde und erschüttert den Boden über ihm, was im Verlauf von 8 Sek. [((12.1% der Angriffskraft) + ((Fernkampfangriffskraft * 0.60) * 0.096)) * 8 * (1 + Vielseitigkeit) * 1 ] Naturschaden verursacht." }
entries[93440] = { ["name"] = "Zwergische Babysöckchen", ["text"] = "Wirken in 2 sek. 5\nZunächst dachtet Ihr, sie wären versteinert. Aber nein, sie sind nur wirklich arg verkrustet.\nZwergische Babysöckchen\nWird beim Aufheben gebunden" }
entries[93441] = { ["name"] = "Halskette mit Anhänger der Elune", ["text"] = "Wirken in 2 sek. 5\nElune ist die oberste Gottheit der Nachtelfen. Sie wird mit dem größeren der beiden Monde in Verbindung gebracht, der Weißen Dame. Obwohl sie eine Göttin des Friedens ist, so ist sie dennoch nicht pazifistisch. Einer ihrer Aspekte ist die Nachtkriegerin, welche die Seelen derer, die sich im Leben als tapfer erwiesen, als Sterne über den Nachthimmel reiten lässt.\nHalskette mit Anhänger der Elune\nWird beim Aufheben gebunden" }
entries[93442] = { ["name"] = "Stück versteinertes Holz", ["text"] = "Wirken in 2 sek. 5\nAuch wenn von dem ursprünglichen Holz nichts mehr vorhanden ist, so ist doch seine Maserung perfekt erhalten. Diese Pflanze war vermutlich ein Exemplar einer Palmen- oder Palmfarnart.\nStück versteinertes Holz\nWird beim Aufheben gebunden" }
entries[93443] = { ["name"] = "Seltsamer pelziger Wurm", ["text"] = "Wirken in 2 sek. 5\nDieses Fossil scheint eine Art fehlendes Verbindungsglied zu sein. Es zeigt sowohl Merkmale von Gliederfüßern als auch Würmern. Sein Körper hat die Gestalt eines Wurms, jedoch insekten- oder krebstierartige Stummelbeine. Anscheinend war die Kreatur auch gänzlich von seidigen Haaren bedeckt.\nSeltsamer pelziger Wurm\nWird beim Aufheben gebunden" }
entries[93444] = { ["name"] = "Feines Besteck der Blutskalpe", ["text"] = "Wirken in 2 sek. 5\nGut, es ist wirklich nur ein großes Messer - aber in einer Kultur wie dem Blutskalpstamm zählt jegliches zum Essen verwendetes Werkzeug als feines Besteck.\nFeines Besteck der Blutskalpe\nWird beim Aufheben gebunden" }
