entries[93825] = { ["name"] = "Champion von Orgrimmar", ["text"] = "Sofort\nIhr tragt die Insignien von Orgrimmar. Jeglicher Rufzuwachs in Dungeons kommt Eurem Ansehen in Orgrimmar zugute." }
entries[93826] = { ["name"] = "Spalten", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nFügt einem Feind und seinen nächsten Verbündeten 110% des normalen Nahkampfschadens zu, wirkt auf bis zu 3 Ziele." }
